const redis = require('redis');

// Function to attempt connection to redis-cluster
async function checkRedisCluster() {
  console.log('Attempting to connect to redis-cluster...');

  try {
    // Create Redis client pointing to 'redis-cluster' service
    const client = redis.createClient({
      host: 'redis-cluster',
      port: 6379,
      retry_strategy: (options) => {
        if (options.attempt > 3) {
          return undefined; // Stop retrying after 3 attempts
        }
        return Math.min(options.attempt * 100, 1000); // Retry after increasing intervals
      }
    });

    // Handle connection errors
    client.on('error', (err) => {
      console.error('Redis connection error:', err.message);
    });

    // Connect to the Redis cluster
    await client.connect();

    // If we reach here, connection was successful
    console.log('Successfully connected to redis-cluster');

    // Test basic operation
    await client.set('healthcheck', 'ok');
    const value = await client.get('healthcheck');
    console.log('Redis healthcheck value:', value);

    // Close the connection
    await client.quit();
    console.log('Connection closed');

  } catch (error) {
    console.error('Failed to connect to redis-cluster:', error.message);
    process.exit(1); // Exit with error code if connection fails
  }
}

// Execute the connection check
checkRedisCluster();

